/************************************************/
/********************************************************/
/* formatage de la zone de recherche de trajet */
/********************************************************/
.traject-container {
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  width: 70% !important;
}
@media screen and (max-width: 425px) {
  .traject-container {
    top: 50% !important;
  }
}
@media screen and (min-width: 768px) {
  .traject-container {
    width: 100%;
    max-width: 100vw;
  }
}

.traject-container .row {
  width: 100%;
  margin: 0;
}

.traject-search-bloc-width {
  width: 100%;
}

#case-depart, #case-arrivee, #case-date, #case-nb-passagers {
  cursor: pointer;
}

.myInput {
  display: flex;
  align-items: center;
  width: 100%;
  height: 100%;
  white-space: nowrap; /* Empêche le retour à la ligne */
  overflow: hidden; /* Cache le texte qui dépasse */
  text-overflow: ellipsis; /* Ajoute des points de suspension à la fin */
  padding-left: 10px;
  /* Masquer le curseur clignotant dans les champs de texte ciblés */
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
}

.search-container {
  display: flex;
  padding: 2px;
  width: 100%;
  height: 100%;
}

.search-container-2 {
  display: flex;
  padding: 2px;
  width: 85%;
}

@media screen and (min-width: 768px) {
  .search-container:hover {
    background-color: var(--custom-gray);
  }
  .search-container:hover #date-picker {
    background-color: var(--custom-gray);
  }
}
/*  certains coins de la première cellule et de la dernière doivent
    s'arrondir différemment selon leur positionnement en ligne ou en colonne*/
.premiere-cellule {
  border-top-left-radius: 20px;
  border-top-right-radius: 20px;
}
@media screen and (min-width: 768px) {
  .premiere-cellule {
    border-top-right-radius: 0;
    border-bottom-left-radius: 20px;
  }
}

.premiere-cellule-2 {
  border-top-left-radius: 18px;
  border-top-right-radius: 18px;
}
@media screen and (min-width: 768px) {
  .premiere-cellule-2 {
    border-top-right-radius: 0;
    border-bottom-left-radius: 18px;
  }
}

.derniere-cellule {
  border-bottom-left-radius: 20px;
