/************************************************************/
/*    animation des flèches d'inversion  départ-arrivée     */
/************************************************************/
#bouncing-arrows {
  z-index: 1500;
}

.arrow-bounce {
  overflow: visible;
}

.arrow-bounce path {
  transition: transform 0.3s ease;
}

/* Animation au survol */
.arrow-bounce:hover path:nth-child(1) {
  animation: moveRight 0.5s ease forwards;
}

.arrow-bounce:hover path:nth-child(2) {
  animation: moveLeft 0.5s ease forwards;
}

/* Animation de la flèche droite */
@keyframes moveRight {
  0% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(2px); /* Va vers la droite */
  }
  100% {
    transform: translateX(0); /* Revient à la position d'origine */
  }
}
/* Animation de la flèche gauche */
@keyframes moveLeft {
  0% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(-2px); /* Va vers la gauche */
  }
  100% {
    transform: translateX(0); /* Revient à la position d'origine */
  }
}
/************************************************************/
/*                  stytle du date-picker                   */
/************************************************************/
.date-picker-div {
  display: flex;
  align-items: center;
}
.date-picker-div:hover {
  background-color: var(--custom-gray);
}

.dropdown-toggle:not(:focus) {
  outline: 0;
}

/****************************************************/
/*              🔍 Menu thème (dropdown) 
/****************************************************/
.theme-icon {
  display: none;
}

/* Afficher l'icône en fonction du mode actif */
[selected-theme=auto] .icon-auto {
  display: flex !important;
}

[selected-theme=light] .icon-light,
[selected-theme=dark] .icon-dark,
[selected-theme=accessibility-light] .icon-accessibility-light,
[selected-theme=accessibility-dark] .icon-accessibility-dark {
  display: flex;
}

/* Masquer toutes les autres icônes en mode auto */
[selected-theme=auto] .theme-icon:not(.icon-auto) {
  display: none !important;
}

.dropdown {
  position: absolute !important;
  top: 15%; /* Ajuste la distance depuis le haut */
  left: 50% !important;
  transform: translate(-50%, 15%) !important;
  z-index: 1050; /* S'assure que le menu est au-dessus */
}
@media screen and (min-width: 768px) {
  .dropdown {
    top: 25%; /* Ajuste la distance depuis le haut */
    left: 50% !important;
    transform: translate(-50%, 25%) !important;
  }
}

.dropdown-menu {
  left: 50% !important;
  transform: translateX(-50%) !important;
  width: -moz-max-content;
  width: max-content;
}

.dropdown-toggle::after {
  border-top-color: var(--custom-primary) !important; /* Change la couleur de la flèche */
}

.dropdown ul {
  background-color: var(--custom-light);
}

/*  formatage des icônes du menu thème */
.icon-color {
  fill: var(--custom-primary) !important;
  stroke: var(--custom-primary) !important;
  stroke-width: 1px;
}

button svg {
  width: 16px;
  height: 16px;
}

svg {
  color: var(--custom-primary); /* Devrait colorer l'icône */
}

svg symbol path {
  stroke-width: 5px !important;
}

.dropdown-item {
  color: var(--custom-primary);
}
.dropdown-item:hover {
  background-color: var(--custom-gray);
}

