  #menu-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: -moz-fit-content;
    width: fit-content;
    cursor: pointer;
    text-decoration: none;
    color: inherit;
    height: auto !important;
    min-height: 40px !important;
    z-index: 9999 !important;
  }
  #menu-list {
    display: flex;
    flex-direction: column;
    list-style: none;
    padding: 5px;
    margin: 0;
    position: absolute;
    top: calc(100% + 5px);
    right: 0;
    border-radius: 5px;
    z-index: 1000;
    overflow: hidden;
    max-height: 0;
    opacity: 0;
    visibility: hidden;
    transition: max-height 2s ease, opacity 0.3s ease, visibility 0.3s ease;
    background-color: var(--custom-light);
    width: 450px;
  }
  #menu-list li a {
    display: flex;
    align-items: center;
    height: 50px;
    width: 100%;
