    display: block !important;
    position: relative;
    height: auto !important;
    min-height: 50px !important;
    overflow: visible !important;
    z-index: 9997;
  }
  /* Quand le menu est ouvert, la flèche tourne vers le haut */
  .show-caret .caret-icon {
    transform: rotate(180deg);
