  #menu {
    width: 100vw;
    padding: 0;
  }
  .my-dropdown-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    text-decoration: none;
    gap: 10px;
  }
  #menu-toggle {
    display: none !important;
  }
  #menu-list {
    display: flex;
    flex-direction: row;
    justify-content: space-around;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
    width: 100%;
    z-index: 1000;
    box-sizing: border-box;
  }
  #menu-list li {
    flex: 1;
    text-align: center;
    padding: 0 !important;
    box-sizing: border-box;
  }
  #menu-list li a {
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    height: 50px;
    text-decoration: none;
    margin: 0;
    box-sizing: border-box;
  }
  #menu-list li a span {
    font-size: 0.9rem;
    font-style: normal;
    font-weight: 200;
  }
  #menu-list li a :hover {
    background-color: var(--custom-gray) !important;
  }
  #menu-list li a .fa-solid {
    padding: 0;
  }
  #menu-div {
    display: flex;
    justify-content: space-between;
    width: 100%;
  }
}
@media screen and (max-width: 425px) {
  #menu-list li a span {
    font-size: 0.75rem;
  }
}
/****************************************************/
/*          Mise en forme du titre                  */
/****************************************************/
.myTitle {
  position: absolute;
  top: 0.5%; /* Ajuste la distance depuis le haut */
  left: 50% !important;
  transform: translate(-50%, 0.5%) !important;
  z-index: 1025; /* S'assure que le menu est au-dessus */
  color: var(--custom-secondary);
  width: auto;
}
@media screen and (min-width: 768px) {
  .myTitle {
    top: 1%; /* Ajuste la distance depuis le haut */
    left: 25% !important;
    transform: translate(-25%, -1%) !important;
  }
}

#page-content {
  will-change: transform, opacity;
}/*# sourceMappingURL=main.css.map */